// Digital twin for Power.L.1T — TI BQ25150 single-cell Li-Ion charger + 1.8 V LDO.
//
// A linear charge controller with an integrated 1.8 V LDO and an ADC. The tile's
// pad map (Power-L-1T-b.json): SUPPLY+ (pad 8, 3.15–5.5 V) / SUPPLY- (pad 9) is
// the charge input; BATT+ (pad 7) / BATT- (pad 6 = BGND) the cell; V+ (pad 10) is
// the 1.8 V LDO out; I²C on pads 4/5; LP (pad 2) wakes from low-power; SW (pad 3)
// to GND disables the LDO.
//
// THE INTERESTING GROUND: the downstream GND (pad 1) is NOT a hard tie — it
// reaches BGND (pad 6) only through an on-board SI8806 MOSFET whose gate is pulled
// from the LDO. So GND(1), BGND/BATT-(6) and SUPPLY-(9) are distinct nets, and
// pad 1's ground is SWITCHED: when the LDO is off (SW→GND, or no power), the
// MOSFET opens and the downstream system's ground floats — a true soft off. The
// twin models pad 1 as a gated ground that follows the LDO.
//
// Conversions mirror the driver (canonical): VBAT/VIN/PMID = raw·6 V/2^16,
// percent = (VBAT-3000)·100/1200 (3.0 V=0%, 4.2 V=100%). Chip currents are
// datasheet (IIN 0.78 mA charge-off, ship 10 nA, active 21 µA w/ LDO). The
// charge/LDO load currents are modeled (external cell + load) → power inferred.
import type { TileSim } from '../tileSim';

const I2C_ADDR = 0x6b;
const LDO_MV = 1800; // tile's fixed LDO output (pad 10), up to 10 mA
const VIN_MIN_MV = 3150; // SUPPLY+ minimum
const VIN_OVP_MV = 5500; // above this, VIN OVP

// chip currents (datasheet Electrical Characteristics)
const IIN_QUIESCENT_UA = 780; // VIN input supply, charge disabled
const IBAT_SHIP_UA = 0.01; // 10 nA ship-mode battery discharge
const IBAT_ACTIVE_LDO_UA = 21; // active, LDO enabled
const IBAT_LP_LDO_UA = 1.7; // low-power, LDO enabled

// LDO modes (power_l_1t_ldo_mode_t)
const LDO_MODE_LDO = 0;
const LDO_MODE_LOAD_SWITCH = 1;

interface State {
  // ── inputs ──
  vin_mv: number; // SUPPLY+ voltage (0 = unplugged)
  batt_mv: number; // cell voltage
  battery_present: number;
  adcin_mv: number; // general-purpose ADC input (pad ADCIN)
  ts_mv: number; // NTC thermistor sense
  fault: number; // VIN OVP / safety-timer / etc.

  // ── charger config ──
  charging_enabled: number;
  charge_current_ma: number; // fast-charge current
  charge_voltage_mv: number; // termination (full) voltage
  precharge_ma: number;
  term_pct: number;
  input_limit_ma: number;

  // ── LDO + power state ──
  ldo_enabled: number;
  ldo_mode: number; // LDO vs load-switch
  sw_grounded: number; // SW pad tied to GND → disables LDO
  lp_mode: number; // low-power mode
  ship: number; // ship mode (battery disconnected)

  // ── TS thresholds (tracked) ──
  ts_cold: number;
  ts_cool: number;
  ts_warm: number;
  ts_hot: number;
  ts_enabled: number;

  [field: string]: number;
}

// STAT0/STAT1 status bits as packed by the driver's status struct order.
const ST_VIN_PGOOD = 1 << 0;
const ST_CHARGING = 1 << 1;
const ST_CV = 1 << 2;
const ST_DONE = 1 << 3;

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

const vinPresent = (s: State) => s.vin_mv >= VIN_MIN_MV && s.vin_mv <= VIN_OVP_MV && s.fault !== 1;
const poweredUp = (s: State) => s.ship !== 1 && (vinPresent(s) || s.battery_present === 1);

// LDO output live: enabled, not shorted off via SW, the part is powered, not shipped.
const ldoOn = (s: State) =>
  s.ldo_enabled === 1 && s.sw_grounded !== 1 && poweredUp(s) && s.ship !== 1;
// The SI8806 ground switch follows the LDO — downstream GND (pad 1) is gated on it.
const gndConnected = (s: State) => ldoOn(s);

function charging(s: State): boolean {
  return (
    vinPresent(s) &&
    s.charging_enabled === 1 &&
    s.battery_present === 1 &&
    s.ship !== 1 &&
    s.batt_mv < s.charge_voltage_mv
  );
}
const chargeDone = (s: State) =>
  vinPresent(s) && s.battery_present === 1 && s.batt_mv >= s.charge_voltage_mv;

// 0–100% fuel gauge: 3.0 V → 0 %, 4.2 V → 100 % (driver's linear map).
const percent = (s: State) => clamp(Math.round(((s.batt_mv - 3000) * 100) / 1200), 0, 100);

function statusByte(s: State): number {
  let b = 0;
  if (vinPresent(s)) b |= ST_VIN_PGOOD;
  if (charging(s)) {
    b |= ST_CHARGING;
    if (s.batt_mv >= s.charge_voltage_mv - 100) b |= ST_CV;
  }
  if (chargeDone(s)) b |= ST_DONE;
  return b;
}

const sim: TileSim<State> = {
  tile: 'Power.L.1T',

  defaultState: {
    vin_mv: 0,
    batt_mv: 3800,
    battery_present: 1,
    adcin_mv: 0,
    ts_mv: 600,
    fault: 0,

    charging_enabled: 1,
    charge_current_ma: 100,
    charge_voltage_mv: 4200,
    precharge_ma: 10,
    term_pct: 10,
    input_limit_ma: 500,

    ldo_enabled: 1,
    ldo_mode: LDO_MODE_LDO,
    sw_grounded: 0,
    lp_mode: 0,
    ship: 0,

    ts_cold: 0,
    ts_cool: 0,
    ts_warm: 0,
    ts_hot: 0,
    ts_enabled: 1,
  },

  controls: [
    {
      type: 'slider',
      field: 'vin_mv',
      label: 'SUPPLY+ in',
      min: 0,
      max: 5500,
      step: 50,
      unit: 'mV',
    },
    {
      type: 'slider',
      field: 'batt_mv',
      label: 'Battery voltage',
      min: 2400,
      max: 4600,
      step: 10,
      unit: 'mV',
    },
    { type: 'toggle', field: 'battery_present', label: 'Battery present' },
    {
      type: 'slider',
      field: 'charge_current_ma',
      label: 'Charge current',
      min: 5,
      max: 500,
      step: 5,
      unit: 'mA',
    },
    { type: 'toggle', field: 'charging_enabled', label: 'Charging enabled' },
    { type: 'toggle', field: 'ldo_enabled', label: 'LDO enabled' },
    { type: 'toggle', field: 'sw_grounded', label: 'SW→GND (LDO off)' },
    { type: 'toggle', field: 'fault', label: 'Fault (OVP/timer)' },
    { type: 'toggle', field: 'ship', label: 'Ship mode' },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_power_l_1t_find: () => ({ scalar: I2C_ADDR }),
    tile_power_l_1t_init: () => ({
      scalar: 0,
      nextState: { charging_enabled: 1, ldo_enabled: 1, ship: 0 },
    }),

    // ── charger config ──
    tile_power_l_1t_set_charge_current_ma: ({ args }) => ({
      nextState: { charge_current_ma: clamp(pick(args, 0, 100), 5, 500) },
    }),
    tile_power_l_1t_set_charge_voltage_mv: ({ args }) => ({
      nextState: { charge_voltage_mv: clamp(pick(args, 0, 4200), 3600, 4600) },
    }),
    tile_power_l_1t_set_pre_charge_ma: ({ args }) => ({
      nextState: { precharge_ma: pick(args, 0, 10) },
    }),
    tile_power_l_1t_set_termination_percent: ({ args }) => ({
      nextState: { term_pct: pick(args, 0, 10) },
    }),
    tile_power_l_1t_set_input_current_limit_ma: ({ args }) => ({
      nextState: { input_limit_ma: clamp(pick(args, 0, 500), 50, 500) },
    }),

    // ── ADC readbacks ──
    tile_power_l_1t_get_vbat_mv: ({ state }) => ({ scalar: state.batt_mv }),
    tile_power_l_1t_get_vin_mv: ({ state }) => ({ scalar: vinPresent(state) ? state.vin_mv : 0 }),
    tile_power_l_1t_get_pmid_mv: ({ state }) => ({
      scalar: vinPresent(state) ? state.vin_mv : state.battery_present ? state.batt_mv : 0,
    }),
    tile_power_l_1t_get_charge_current_ma: ({ state }) => ({
      scalar: charging(state) ? state.charge_current_ma : 0,
    }),
    tile_power_l_1t_get_input_current_ma: ({ state }) => ({
      scalar: vinPresent(state)
        ? (charging(state) ? state.charge_current_ma : 0) + Math.round(IIN_QUIESCENT_UA / 1000)
        : 0,
    }),
    tile_power_l_1t_get_ts_mv: ({ state }) => ({ scalar: state.ts_mv }),
    tile_power_l_1t_get_adcin_mv: ({ state }) => ({ scalar: state.adcin_mv }),
    tile_power_l_1t_get_percent: ({ state }) => ({ scalar: percent(state) }),

    // ── TS thresholds ──
    tile_power_l_1t_set_ts_cold: ({ args }) => ({ nextState: { ts_cold: pick(args, 0, 0) } }),
    tile_power_l_1t_set_ts_cool: ({ args }) => ({ nextState: { ts_cool: pick(args, 0, 0) } }),
    tile_power_l_1t_set_ts_warm: ({ args }) => ({ nextState: { ts_warm: pick(args, 0, 0) } }),
    tile_power_l_1t_set_ts_hot: ({ args }) => ({ nextState: { ts_hot: pick(args, 0, 0) } }),
    tile_power_l_1t_set_ts_enabled: ({ args }) => ({
      nextState: { ts_enabled: pick(args, 0, 1) ? 1 : 0 },
    }),

    // ── LDO ──
    tile_power_l_1t_set_ldo_voltage_mv: () => ({ nextState: {} }), // fixed 1.8 V on this tile
    tile_power_l_1t_set_ldo_mode: ({ args }) => ({
      nextState: { ldo_mode: pick(args, 0, LDO_MODE_LDO) ? LDO_MODE_LOAD_SWITCH : LDO_MODE_LDO },
    }),
    tile_power_l_1t_set_ldo_enabled: ({ args }) => ({
      nextState: { ldo_enabled: pick(args, 0, 1) ? 1 : 0 },
    }),

    // ── status ──
    tile_power_l_1t_get_charge_status: ({ state }) => ({ scalar: statusByte(state) }),
    tile_power_l_1t_read_status: ({ state }) => ({ scalar: statusByte(state) }),
    tile_power_l_1t_is_charging: ({ state }) => ({ scalar: charging(state) ? 1 : 0 }),
    tile_power_l_1t_is_charge_done: ({ state }) => ({ scalar: chargeDone(state) ? 1 : 0 }),
    tile_power_l_1t_is_battery_low: ({ state, args }) => ({
      scalar: percent(state) < pick(args, 0, 20) ? 1 : 0,
    }),
    tile_power_l_1t_is_powered: ({ state }) => ({ scalar: vinPresent(state) ? 1 : 0 }),
    tile_power_l_1t_wait_for_charge_done: ({ state }) => ({ scalar: chargeDone(state) ? 1 : 0 }),

    // ── power management / raw ──
    tile_power_l_1t_enter_ship_mode: () => ({ nextState: { ship: 1 } }),
    tile_power_l_1t_write_reg: () => ({ nextState: {} }),
  },

  provenance: {
    // canonical — datasheet/driver-accurate
    tile_power_l_1t_find: 'canonical', // I2C 0x6B
    tile_power_l_1t_get_vbat_mv: 'canonical', // raw·6V/2^16
    tile_power_l_1t_get_vin_mv: 'canonical',
    tile_power_l_1t_get_pmid_mv: 'canonical',
    tile_power_l_1t_get_percent: 'canonical', // (VBAT-3000)·100/1200
    tile_power_l_1t_get_charge_status: 'canonical', // STAT0/1 bits
    tile_power_l_1t_is_charging: 'canonical',
    tile_power_l_1t_is_charge_done: 'canonical',
    tile_power_l_1t_is_powered: 'canonical', // VIN PGOOD
    tile_power_l_1t_set_charge_current_ma: 'canonical', // 5-500 mA
    tile_power_l_1t_set_charge_voltage_mv: 'canonical', // 3.6-4.6 V
    tile_power_l_1t_set_ldo_mode: 'canonical', // LDO vs load-switch
    tile_power_l_1t_enter_ship_mode: 'canonical', // ICCTRL0 ship bit
    // inferred — modeled charge/LDO behavior
    tile_power_l_1t_init: 'inferred',
    tile_power_l_1t_set_pre_charge_ma: 'inferred',
    tile_power_l_1t_set_termination_percent: 'inferred',
    tile_power_l_1t_set_input_current_limit_ma: 'inferred',
    tile_power_l_1t_get_charge_current_ma: 'inferred',
    tile_power_l_1t_get_input_current_ma: 'inferred',
    tile_power_l_1t_get_ts_mv: 'inferred',
    tile_power_l_1t_get_adcin_mv: 'inferred',
    tile_power_l_1t_set_ts_cold: 'inferred',
    tile_power_l_1t_set_ts_cool: 'inferred',
    tile_power_l_1t_set_ts_warm: 'inferred',
    tile_power_l_1t_set_ts_hot: 'inferred',
    tile_power_l_1t_set_ts_enabled: 'inferred',
    tile_power_l_1t_set_ldo_enabled: 'inferred',
    tile_power_l_1t_read_status: 'inferred',
    tile_power_l_1t_is_battery_low: 'inferred',
    tile_power_l_1t_wait_for_charge_done: 'inferred',
    // hallucinated — not modeled on this tile
    tile_power_l_1t_set_ldo_voltage_mv: 'hallucinated', // LDO is hardware-fixed at 1.8 V here
    tile_power_l_1t_write_reg: 'hallucinated',
    power: 'inferred', // chip Iq canonical; charge/LDO load currents modeled
  },

  // V+ (LDO, pad 10) + the SWITCHED ground (pad 1, gated by the SI8806 off the LDO).
  padOutputs(state) {
    return {
      'V+(1.8V)': ldoOn(state) ? 1 : 0,
      'GND(sw)': gndConnected(state) ? 1 : 0,
    };
  },

  // Electrical. Three distinct grounds: SUPPLY- (9), BATT-/BGND (6), switched
  // GND (1). On VIN the input supplies charge + system; on battery the cell does
  // (down to ship-mode 10 nA). The LDO sources V+ (pad 10, returns to switched
  // GND pad 1). Chip quiescents are datasheet; the charge/LDO loads are modeled.
  power(state) {
    const onVin = vinPresent(state);
    const charge_ua = charging(state) ? state.charge_current_ma * 1000 : 0;
    const rails: NonNullable<ReturnType<NonNullable<TileSim<State>['power']>>['rails']> = [];

    if (onVin) {
      rails.push({
        name: 'SUPPLY',
        role: 'supply',
        v_mv: state.vin_mv,
        i_ua: charge_ua + IIN_QUIESCENT_UA,
        pads: ['8'],
        note: charging(state) ? 'input — charging + system' : 'input',
      });
      rails.push({
        name: 'BATT',
        role: 'supply',
        v_mv: state.batt_mv,
        i_ua: 0,
        pads: ['7'],
        note: 'battery receiving charge',
      });
    } else {
      // On battery: the cell sources everything; quiescent depends on mode.
      const battUa =
        state.ship === 1 ? IBAT_SHIP_UA : state.lp_mode === 1 ? IBAT_LP_LDO_UA : IBAT_ACTIVE_LDO_UA;
      rails.push({
        name: 'BATT',
        role: 'supply',
        v_mv: state.battery_present ? state.batt_mv : 0,
        i_ua: state.battery_present ? battUa : 0,
        pads: ['7'],
        note:
          state.ship === 1 ? 'battery — ship mode (disconnected)' : 'battery input (discharging)',
      });
    }

    rails.push({
      name: 'V+',
      role: 'output',
      v_mv: ldoOn(state) ? LDO_MV : 0,
      pads: ['10'],
      note: ldoOn(state)
        ? '1.8 V LDO (ground via pad 1 switch)'
        : 'LDO off — pad 1 ground also open',
    });

    const draw = onVin
      ? charge_ua + IIN_QUIESCENT_UA
      : state.battery_present
        ? state.ship === 1
          ? IBAT_SHIP_UA
          : state.lp_mode === 1
            ? IBAT_LP_LDO_UA
            : IBAT_ACTIVE_LDO_UA
        : 0;
    return { draw_ua: Math.round(draw), rails };
  },
};

export default sim;
